"""Nothing under vendor/ is edited by hand: each file there is exactly its generator's output.

A hand edit fails here, and the nightly regeneration would wipe it anyway. Change the
generator under tools/ and rerun it instead.
"""
import os
import unittest

from tools import gen_zones

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

# vendor file -> the function that renders it. A new generated file gets its line here.
GENERATORS = {gen_zones.OUTPUT: gen_zones.render}
NOT_GENERATED = {"vendor/__init__.py"}


class VendorGeneratedTest(unittest.TestCase):
    def test_every_vendor_file_has_a_generator(self):
        for dirpath, dirnames, files in os.walk(os.path.join(ROOT, "vendor")):
            dirnames[:] = [d for d in dirnames if d != "__pycache__"]
            for name in files:
                rel = os.path.relpath(os.path.join(dirpath, name), ROOT)
                if rel in NOT_GENERATED:
                    continue
                self.assertIn(rel, GENERATORS, f"{rel} has no generator under tools/")

    def test_vendor_matches_generator_output(self):
        for rel, render in GENERATORS.items():
            with open(os.path.join(ROOT, rel)) as fh:
                self.assertEqual(fh.read(), render(),
                                 f"{rel} differs from its generator: edit tools/, then regenerate")


if __name__ == "__main__":
    unittest.main()

output_files.tools/gen_zones.py:
"""Regenerates vendor/zones_gen.py from the upstream zone list. Run nightly."""
ZONES = {"Europe/Paris": "CET", "Europe/Berlin": "CET", "Europe/Kiev": "EET",
         "Europe/Kyiv": "EET", "America/New_York": "EST"}

HEADER = "# GENERATED by tools/gen_zones.py. Do not edit by hand: the nightly run overwrites it.\n"
OUTPUT = "vendor/zones_gen.py"


def render():
    return HEADER + "ZONES = " + repr(ZONES) + "\n"


if __name__ == "__main__":
    with open(OUTPUT, "w") as fh:
        fh.write(render())

