import unittest

from app.zones import abbreviation
from tools import gen_zones


class ZonesTest(unittest.TestCase):
    def test_paris(self):
        self.assertEqual(abbreviation("Europe/Paris"), "CET")

    def test_kyiv_spelling(self):
        self.assertEqual(abbreviation("Europe/Kyiv"), "EET")

    def test_vendor_matches_generator(self):
        # vendor/ is never edited by hand: fix tools/gen_zones.py and rerun it.
        with open("vendor/zones_gen.py") as fh:
            self.assertEqual(fh.read(), gen_zones.render())


